INSERT OR IGNORE INTO "pages" (id, slug, title, content, meta, published) VALUES
('page-home','home','Home','{"hero":{"badge":"Skill-First, Career-Focused","headline":"Learn to Code,","subheadline":"Acquire job-ready skills through hands-on projects, guided mentorship, and a curriculum built by industry professionals — skills you can use from day one.","typing":["Master In-Demand Skills","Build Real-World Projects","Ship Production Apps","Earn Industry Certification"],"primaryLabel":"Start Building Skills","primaryHref":"/signup","secondaryLabel":"Explore Programs","secondaryHref":"/courses"},"trust":{"heading":"Built for real outcomes","subheading":"No invented placement stats or borrowed logos — just the things we actually build into every programme."},"faq":{"heading":"Frequently Asked Questions","subheading":"Got questions? We have answers. Cannot find what you are looking for? Contact our support team."},"cta":{"heading":"Build Hire-Ready Skills","body":"Join thousands of learners turning hands-on practice into a portfolio employers can verify — then apply to roles directly through our in-platform career pipeline."}}','{"title":"Learn In-Demand Tech Skills & Launch Your Career","description":"CareerCode Academy is the education venture of WID LTD. Learn practical technology skills through projects, mentorship and verifiable certificates."}',1),
('page-about','about','About','{"hero":{"title":"Practical Tech Education, Built by WID LTD","paragraph1":"CareerCode Academy is the education venture of WID LTD, a Nigerian technology company built on the philosophy of Unlimited Capability. We help beginners become job-ready developers through structured curriculum, real projects and human support.","paragraph2":"We believe technology education should be practical, honest and reachable. Our programmes combine engineering rigour with the support learners need to finish.","location":"Agbara, Ogun State, Nigeria"},"mission":"To engineer dependable systems and learning experiences that institutions and startups alike can stake their growth on.","vision":"A digitally self-reliant Africa delivering technology the world depends on — starting with the people who build it.","contact":{"email":"contact@widltd.com.ng","phone":"+234 816 496 1457","office":"Agbara, Ogun State, Nigeria","hours":"Mon–Fri, 8:00 AM – 6:00 PM WAT"}}','{"title":"About","description":"CareerCode Academy is the education venture of WID LTD (RC 8824091), a Nigerian technology company based in Agbara, Ogun State."}',1),
('page-contact','contact','Contact','{"heading":"Get in Touch","subheading":"Have a question, feedback, or just want to say hello? We would love to hear from you.","email":"contact@widltd.com.ng","supportEmail":"hello@careercode.com.ng","phone":"+234 816 496 1457","office":"Agbara, Ogun State, Nigeria","hours":"Mon–Fri, 8:00 AM – 6:00 PM WAT","successMessage":"We will get back to you within 24 hours."}','{"title":"Contact","description":"Contact CareerCode Academy, the education venture of WID LTD (RC 8824091), Agbara, Ogun State, Nigeria."}',1),
('page-faq','faq','Frequently Asked Questions','{"items":[{"question":"Do I need prior coding experience to join?","answer":"Not at all. Our courses range from beginner to advanced levels. We have structured paths for complete beginners with no prior experience, as well as advanced tracks for experienced developers looking to upskill."},{"question":"How long does it take to complete a course?","answer":"Course duration varies from 8 to 24 weeks depending on the programme. Most students complete our flagship Full-Stack Web Development course in 16 weeks by dedicating 15 to 20 hours per week."},{"question":"Is there a job guarantee?","answer":"We do not publish placement guarantees. Instead, we build a transparent in-platform career pipeline: track your progress toward specific career outcomes, apply to partnered roles directly from the academy, and publish a public learner profile with your certificates and projects for employers to discover."},{"question":"What kind of projects will I build?","answer":"You will build real-world projects that mirror industry requirements. Examples include e-commerce platforms, social media dashboards, data visualisation tools, and mobile apps that you can add to your portfolio."},{"question":"Do you offer payment plans?","answer":"Yes. We offer flexible payment plans including monthly instalments and need-based scholarships. Contact our admissions team to discuss options that work for you."},{"question":"Can I interact with instructors and mentors?","answer":"Absolutely. Each student is assigned a dedicated mentor who provides one-on-one guidance. Our instructors hold weekly live question sessions, and you can ask questions in our community forums anytime."}]}','{"title":"Frequently Asked Questions","description":"Answers to common questions about learning at CareerCode Academy."}',1),
('page-footer','footer','Footer','{"description":"CareerCode Academy is the education venture of WID LTD (RC 8824091) — practical, project-based learning for people building technology careers.","tagline":"WID LTD — The Motivation for Innovation. Registered in Nigeria, September 2025.","copyright":"CareerCode Academy. All rights reserved."}','{}',1);
